static void xl6CgenEmitTlsRuntime(XL6_Output* out)
{
    /* 原始 TLS 状态机由 XRT 实现；这里仅负责配置、Buffer 与所有权适配。 */
    xl6OutputPuts("typedef struct xrt_tls_session xtlssession;\n", out);
    xl6OutputPuts("typedef struct xrt_tls_resume xtlsresume;\n", out);
    xl6OutputPuts("#ifndef XL6_XRT_TLS_CONFIG_TYPE\n", out);
    xl6OutputPuts("#define XL6_XRT_TLS_CONFIG_TYPE\n", out);
    xl6OutputPuts("typedef bool (*xtlsverifyproc)(xtlssession*, const void*, size_t, bool, void*);\n", out);
    xl6OutputPuts("typedef struct xtlsconfig {\n", out);
    xl6OutputPuts("    const char* sCertFile; const char* sKeyFile; const char* sCaFile; const char* sCrlFile;\n", out);
    xl6OutputPuts("    const void* pCertData; size_t iCertDataLen; const void* pKeyData; size_t iKeyDataLen;\n", out);
    xl6OutputPuts("    const void* pCaData; size_t iCaDataLen; const void* pCrlData; size_t iCrlDataLen;\n", out);
    xl6OutputPuts("    const char* sHostName; const char* sAlpnProtocols; bool bVerifyPeer;\n", out);
    xl6OutputPuts("    void (*OnSNI)(xtlssession*, const char*, void*); void* pSNIUserData;\n", out);
    xl6OutputPuts("    xtlsverifyproc OnVerify; void* pVerifyUserData;\n", out);
    xl6OutputPuts("    bool bAllowTLS12Ed25519; uint16_t iMaxVersion; const xtlsresume* pResume; volatile long iDataLock;\n", out);
    xl6OutputPuts("} xtlsconfig;\n", out);
    xl6OutputPuts("#endif\n\n", out);
    xl6OutputPuts("typedef struct XL6_TlsConfig {\n", out);
    xl6OutputPuts("    xtlsconfig value;\n", out);
    xl6OutputPuts("    char* certFile; char* keyFile; char* caFile; char* crlFile; char* hostName; char* alpnProtocols;\n", out);
    xl6OutputPuts("    void* certData; size_t certSize; void* keyData; size_t keySize;\n", out);
    xl6OutputPuts("    void* caData; size_t caSize; void* crlData; size_t crlSize;\n", out);
    xl6OutputPuts("#ifdef XL6_FUNCTION_VAR_RUNTIME\n", out);
    xl6OutputPuts("    XL6_Function verifyCallback;\n    int hasVerifyCallback;\n", out);
    xl6OutputPuts("#endif\n", out);
    xl6OutputPuts("} XL6_TlsConfig;\n", out);
    xl6OutputPuts("typedef struct XL6_TlsSession { xtlssession* value; int lastStatus; } XL6_TlsSession;\n\n", out);
    xl6OutputPuts("void* xrtMalloc(size_t iSize);\nvoid* xrtCalloc(size_t iCount, size_t iSize);\nvoid xrtFree(void* pMem);\n", out);
    xl6OutputPuts("char* xrtCopyStr(const char* sText, size_t iSize);\nvoid* xrtCopyMem(void* pMem, size_t iSize);\n", out);
    xl6OutputPuts("xtlssession* xrtNetTlsSessionCreate(const xtlsconfig* pCfg, bool bIsServer);\n", out);
    xl6OutputPuts("void xrtNetTlsSessionDestroy(xtlssession* pSession);\nbool xrtNetTlsSessionIsReady(const xtlssession* pSession);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionDriveHandshake(xtlssession* pSession);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionFeedCipher(xtlssession* pSession, const void* pData, size_t iLen);\n", out);
    xl6OutputPuts("size_t xrtNetTlsSessionPendingCipher(const xtlssession* pSession);\nsize_t xrtNetTlsSessionPendingRecv(const xtlssession* pSession);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionPeekCipher(xtlssession* pSession, void* pBuf, size_t iLen, size_t* pRead);\n", out);
    xl6OutputPuts("void xrtNetTlsSessionConsumeCipher(xtlssession* pSession, size_t iLen);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionWritePlain(xtlssession* pSession, const void* pData, size_t iLen, size_t* pWritten);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionReadPlain(xtlssession* pSession, void* pBuf, size_t iLen, size_t* pRead);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionQueueClose(xtlssession* pSession);\n", out);
    xl6OutputPuts("xtlsresume* xrtNetTlsSessionExportResume(const xtlssession* pSession);\nvoid xrtNetTlsResumeDestroy(xtlsresume* pResume);\n", out);
    xl6OutputPuts("bool xrtNetTlsSessionWasResumed(const xtlssession* pSession);\nconst char* xrtNetTlsSessionGetSNI(const xtlssession* pSession);\nconst char* xrtNetTlsSessionGetALPN(const xtlssession* pSession);\n", out);
    xl6OutputPuts("const void* xrtNetTlsSessionPeerCertDer(const xtlssession* pSession, size_t* pSize);\nsize_t xrtNetTlsSessionPeerCertSize(const xtlssession* pSession);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionSetCert(xtlssession* pSession, const char* sCertFile, const char* sKeyFile);\n", out);
    xl6OutputPuts("int xrtNetTlsSessionSetCertData(xtlssession* pSession, const void* pCertData, size_t iCertLen, const void* pKeyData, size_t iKeyLen);\n", out);
    xl6OutputPuts("void xrtNetTlsSessionSetAllowTLS12Ed25519(xtlssession* pSession, bool bAllow);\n\n", out);

    xl6OutputPuts("static bool xl6_tls_replace_string(char** target, const char* value)\n{\n", out);
    xl6OutputPuts("    char* copy = xrtCopyStr(value != 0 ? value : \"\", 0);\n", out);
    xl6OutputPuts("    if ( copy == 0 ) { return false; }\n", out);
    xl6OutputPuts("    if ( *target != 0 ) { xrtFree(*target); }\n    *target = copy;\n    return true;\n}\n\n", out);
    xl6OutputPuts("static bool xl6_tls_replace_bytes(void** target, size_t* targetSize, const void* data, size_t size)\n{\n", out);
    xl6OutputPuts("    void* copy = 0;\n    if ( size > 0u ) { if ( data == 0 ) { return false; } copy = xrtCopyMem((void*)data, size); if ( copy == 0 ) { return false; } }\n", out);
    xl6OutputPuts("    if ( *target != 0 ) { xrtFree(*target); }\n    *target = copy;\n    *targetSize = size;\n    return true;\n}\n\n", out);

    xl6OutputPuts("#ifdef XL6_FUNCTION_VAR_RUNTIME\n", out);
    xl6OutputPuts("#ifndef XL6_XVALUE_TYPEDEF\n#define XL6_XVALUE_TYPEDEF\n", out);
    xl6OutputPuts("typedef struct xvalue_struct* xvalue;\n", out);
    xl6OutputPuts("#endif\n", out);
    xl6OutputPuts("void* xrtHexEncode(void* pMem, size_t iSize);\n", out);
    xl6OutputPuts("xvalue xvoCreateTable(void);\nxvalue xvoCreateBool(bool value);\nxvalue xvoCreateInt(long long value);\nxvalue xvoCreateText(void* text, unsigned int size, bool colloc);\n", out);
    xl6OutputPuts("bool xvoTableSetValue(xvalue table, const void* key, unsigned int keySize, xvalue value, bool colloc);\nbool xvoGetBool(xvalue value);\nvoid xvoUnref(xvalue value);\n", out);
    xl6OutputPuts("static xvalue xl6_function_call_var(XL6_Function fn, int argc, ...);\n", out);
    xl6OutputPuts("static bool xl6_tls_event_set(xvalue event, const char* key, xvalue value)\n{\n", out);
    xl6OutputPuts("    if ( event == 0 || value == 0 ) { if ( value != 0 ) { xvoUnref(value); } return false; }\n", out);
    xl6OutputPuts("    if ( !xvoTableSetValue(event, key, 0u, value, true) ) { xvoUnref(value); return false; }\n", out);
    xl6OutputPuts("    return true;\n}\n\n", out);
    xl6OutputPuts("static bool xl6_tls_verify_callback_call(xtlssession* session, const void* certDer, size_t certSize, bool defaultOk, void* userData)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* config = (XL6_TlsConfig*)userData;\n    xvalue event;\n    xvalue result;\n    char* certHex = 0;\n    bool accepted;\n    (void)session;\n", out);
    xl6OutputPuts("    if ( config == 0 || !config->hasVerifyCallback ) { return defaultOk; }\n", out);
    xl6OutputPuts("    event = xvoCreateTable();\n    if ( event == 0 ) { return false; }\n", out);
    xl6OutputPuts("    if ( certDer != 0 && certSize > 0u ) { certHex = (char*)xrtHexEncode((void*)certDer, certSize); }\n", out);
    xl6OutputPuts("    if ( !xl6_tls_event_set(event, \"defaultOk\", xvoCreateBool(defaultOk)) ||\n         !xl6_tls_event_set(event, \"certSize\", xvoCreateInt((long long)certSize)) ||\n         !xl6_tls_event_set(event, \"certHex\", xvoCreateText((void*)(certHex != 0 ? certHex : \"\"), 0u, false)) ) {\n        if ( certHex != 0 ) { xrtFree(certHex); }\n        xvoUnref(event);\n        return false;\n    }\n", out);
    xl6OutputPuts("    if ( certHex != 0 ) { xrtFree(certHex); }\n", out);
    xl6OutputPuts("    result = xl6_function_call_var(config->verifyCallback, 1, event);\n", out);
    xl6OutputPuts("    accepted = result != 0 ? xvoGetBool(result) : false;\n", out);
    xl6OutputPuts("    if ( result != 0 ) { xvoUnref(result); }\n", out);
    xl6OutputPuts("    return accepted;\n}\n\n", out);
    xl6OutputPuts("#endif\n\n", out);

    xl6OutputPuts("void* xl6_xrt_tls_config_create(void)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* config = (XL6_TlsConfig*)xrtCalloc(1u, sizeof(XL6_TlsConfig));\n", out);
    xl6OutputPuts("    if ( config != 0 ) { config->value.bVerifyPeer = true; config->value.bAllowTLS12Ed25519 = true; }\n", out);
    xl6OutputPuts("    return config;\n}\n\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_config_destroy(void* handle)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* config = (XL6_TlsConfig*)handle;\n    if ( config == 0 ) { return 0; }\n", out);
    xl6OutputPuts("#ifdef XL6_FUNCTION_VAR_RUNTIME\n", out);
    xl6OutputPuts("    if ( config->hasVerifyCallback ) { xl6_function_release_value(config->verifyCallback); config->hasVerifyCallback = 0; }\n", out);
    xl6OutputPuts("#endif\n", out);
    xl6OutputPuts("    xrtFree(config->certFile); xrtFree(config->keyFile); xrtFree(config->caFile); xrtFree(config->crlFile); xrtFree(config->hostName); xrtFree(config->alpnProtocols);\n", out);
    xl6OutputPuts("    xrtFree(config->certData); xrtFree(config->keyData); xrtFree(config->caData); xrtFree(config->crlData);\n", out);
    xl6OutputPuts("    memset(config, 0, sizeof(*config)); xrtFree(config); return 0;\n}\n\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_config_native(void* handle) { return handle; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_host(void* handle, const char* host)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_string(&c->hostName, host) ) { return false; } c->value.sHostName = c->hostName; return true;\n}\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_alpn(void* handle, const char* protocols)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_string(&c->alpnProtocols, protocols) ) { return false; } c->value.sAlpnProtocols = c->alpnProtocols; return true;\n}\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_cert(void* handle, const char* cert, const char* key)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; char* certCopy; char* keyCopy; if ( c == 0 ) { return false; } certCopy = xrtCopyStr(cert != 0 ? cert : \"\", 0); keyCopy = xrtCopyStr(key != 0 ? key : \"\", 0); if ( certCopy == 0 || keyCopy == 0 ) { xrtFree(certCopy); xrtFree(keyCopy); return false; } xrtFree(c->certFile); xrtFree(c->keyFile); c->certFile = certCopy; c->keyFile = keyCopy; c->value.sCertFile = certCopy; c->value.sKeyFile = keyCopy; return true;\n}\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_ca(void* handle, const char* ca)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_string(&c->caFile, ca) ) { return false; } c->value.sCaFile = c->caFile; return true;\n}\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_crl(void* handle, const char* crl)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_string(&c->crlFile, crl) ) { return false; } c->value.sCrlFile = c->crlFile; return true;\n}\n", out);
    xl6OutputPuts("void xl6_xrt_tls_config_verify(void* handle, int verify) { XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c != 0 ) { c->value.bVerifyPeer = verify != 0; } }\n", out);
    xl6OutputPuts("void xl6_xrt_tls_config_allow_ed25519(void* handle, int allow) { XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c != 0 ) { c->value.bAllowTLS12Ed25519 = allow != 0; } }\n", out);
    xl6OutputPuts("void xl6_xrt_tls_config_max_version(void* handle, long long version) { XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c != 0 ) { c->value.iMaxVersion = version > 0 && version <= 65535 ? (uint16_t)version : 0u; } }\n", out);
    xl6OutputPuts("#ifdef XL6_FUNCTION_VAR_RUNTIME\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_verify_callback(void* handle, XL6_Function fn)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle;\n    if ( c == 0 || (fn.invoke_var == 0 && fn.invoke_xcall == 0) ) { return false; }\n", out);
    xl6OutputPuts("    if ( c->hasVerifyCallback ) { xl6_function_release_value(c->verifyCallback); c->hasVerifyCallback = 0; }\n", out);
    xl6OutputPuts("    c->verifyCallback = xl6_function_copy_value(fn);\n    c->hasVerifyCallback = 1;\n    c->value.OnVerify = xl6_tls_verify_callback_call;\n    c->value.pVerifyUserData = c;\n    return true;\n}\n", out);
    xl6OutputPuts("#endif\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_cert_data(void* handle, void* cert, size_t certSize, void* key, size_t keySize)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* c = (XL6_TlsConfig*)handle; void* certCopy = 0; void* keyCopy = 0; if ( c == 0 || (certSize > 0u && cert == 0) || (keySize > 0u && key == 0) ) { return false; } if ( certSize > 0u ) { certCopy = xrtCopyMem(cert, certSize); } if ( keySize > 0u ) { keyCopy = xrtCopyMem(key, keySize); } if ( (certSize > 0u && certCopy == 0) || (keySize > 0u && keyCopy == 0) ) { xrtFree(certCopy); xrtFree(keyCopy); return false; } xrtFree(c->certData); xrtFree(c->keyData); c->certData = certCopy; c->certSize = certSize; c->keyData = keyCopy; c->keySize = keySize; c->value.pCertData = certCopy; c->value.iCertDataLen = certSize; c->value.pKeyData = keyCopy; c->value.iKeyDataLen = keySize; return true;\n}\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_ca_data(void* handle, void* data, size_t size)\n{ XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_bytes(&c->caData, &c->caSize, data, size) ) { return false; } c->value.pCaData = c->caData; c->value.iCaDataLen = c->caSize; return true; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_config_crl_data(void* handle, void* data, size_t size)\n{ XL6_TlsConfig* c = (XL6_TlsConfig*)handle; if ( c == 0 || !xl6_tls_replace_bytes(&c->crlData, &c->crlSize, data, size) ) { return false; } c->value.pCrlData = c->crlData; c->value.iCrlDataLen = c->crlSize; return true; }\n\n", out);

    xl6OutputPuts("void* xl6_xrt_tls_session_create(void* configHandle, int server, void* resumeHandle)\n{\n", out);
    xl6OutputPuts("    XL6_TlsConfig* config = (XL6_TlsConfig*)configHandle; XL6_TlsSession* outSession; xtlsconfig local;\n", out);
    xl6OutputPuts("    if ( config != 0 ) { local = config->value; } else { memset(&local, 0, sizeof(local)); local.bVerifyPeer = true; local.bAllowTLS12Ed25519 = true; }\n", out);
    xl6OutputPuts("    local.pResume = (const xtlsresume*)resumeHandle; outSession = (XL6_TlsSession*)xrtCalloc(1u, sizeof(XL6_TlsSession)); if ( outSession == 0 ) { return 0; }\n", out);
    xl6OutputPuts("    outSession->value = xrtNetTlsSessionCreate(&local, server); if ( outSession->value == 0 ) { xrtFree(outSession); return 0; } return outSession;\n}\n\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_destroy(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return 0; } xrtNetTlsSessionDestroy(s->value); s->value = 0; xrtFree(s); return 0; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_session_ready(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 && xrtNetTlsSessionIsReady(s->value); }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_drive(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return -1; } s->lastStatus = xrtNetTlsSessionDriveHandshake(s->value); return s->lastStatus; }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_feed(void* handle, void* data, size_t size) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return -1; } s->lastStatus = xrtNetTlsSessionFeedCipher(s->value, data, size); return s->lastStatus; }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_pending_cipher(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 ? (long long)xrtNetTlsSessionPendingCipher(s->value) : 0; }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_pending_plain(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 ? (long long)xrtNetTlsSessionPendingRecv(s->value) : 0; }\n", out);
    xl6OutputPuts("static xbuffer xl6_tls_read_buffer(XL6_TlsSession* session, int maxBytes, bool cipher)\n{\n", out);
    xl6OutputPuts("    size_t available; size_t wanted; size_t readSize = 0u; void* data; xbuffer buffer; if ( session == 0 ) { return xrtBufferCreate(0u); } available = cipher ? xrtNetTlsSessionPendingCipher(session->value) : xrtNetTlsSessionPendingRecv(session->value); wanted = maxBytes > 0 && (size_t)maxBytes < available ? (size_t)maxBytes : available; if ( wanted == 0u ) { return xrtBufferCreate(0u); } data = xrtMalloc(wanted); if ( data == 0 ) { return 0; } session->lastStatus = cipher ? xrtNetTlsSessionPeekCipher(session->value, data, wanted, &readSize) : xrtNetTlsSessionReadPlain(session->value, data, wanted, &readSize); if ( session->lastStatus != 0 && session->lastStatus != -2 ) { xrtFree(data); return xrtBufferCreate(0u); } buffer = (xbuffer)xl6_xrt_buffer_from_owned_bytes(data, readSize); return buffer;\n}\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_peek_cipher(void* handle, long long maxBytes) { return xl6_tls_read_buffer((XL6_TlsSession*)handle, maxBytes > 2147483647LL ? 2147483647 : (int)maxBytes, true); }\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_read_plain(void* handle, long long maxBytes) { return xl6_tls_read_buffer((XL6_TlsSession*)handle, maxBytes > 2147483647LL ? 2147483647 : (int)maxBytes, false); }\n", out);
    xl6OutputPuts("void xl6_xrt_tls_session_consume_cipher(void* handle, long long size) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s != 0 && size > 0 ) { xrtNetTlsSessionConsumeCipher(s->value, (size_t)size); } }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_write_plain(void* handle, void* data, size_t size) { XL6_TlsSession* s = (XL6_TlsSession*)handle; size_t written = 0u; if ( s == 0 ) { return -1; } s->lastStatus = xrtNetTlsSessionWritePlain(s->value, data, size, &written); return s->lastStatus == 0 ? (long long)written : (long long)s->lastStatus; }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_close(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return -1; } s->lastStatus = xrtNetTlsSessionQueueClose(s->value); return s->lastStatus; }\n", out);
    xl6OutputPuts("long long xl6_xrt_tls_session_last_status(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 ? s->lastStatus : -1; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_session_resumed(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 && xrtNetTlsSessionWasResumed(s->value); }\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_sni(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; const char* text = s != 0 ? xrtNetTlsSessionGetSNI(s->value) : 0; return xrtCopyStr(text != 0 ? text : \"\", 0); }\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_alpn(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; const char* text = s != 0 ? xrtNetTlsSessionGetALPN(s->value) : 0; return xrtCopyStr(text != 0 ? text : \"\", 0); }\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_peer_cert(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; size_t size = 0u; const void* data = s != 0 ? xrtNetTlsSessionPeerCertDer(s->value, &size) : 0; void* copy; if ( data == 0 || size == 0u ) { return xrtBufferCreate(0u); } copy = xrtCopyMem((void*)data, size); if ( copy == 0 ) { return 0; } return xl6_xrt_buffer_from_owned_bytes(copy, size); }\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_session_export_resume(void* handle) { XL6_TlsSession* s = (XL6_TlsSession*)handle; return s != 0 ? xrtNetTlsSessionExportResume(s->value) : 0; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_session_set_cert(void* handle, const char* cert, const char* key) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return false; } s->lastStatus = xrtNetTlsSessionSetCert(s->value, cert, key); return s->lastStatus == 0; }\n", out);
    xl6OutputPuts("int xl6_xrt_tls_session_set_cert_data(void* handle, void* cert, size_t certSize, void* key, size_t keySize) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s == 0 ) { return false; } s->lastStatus = xrtNetTlsSessionSetCertData(s->value, cert, certSize, key, keySize); return s->lastStatus == 0; }\n", out);
    xl6OutputPuts("void xl6_xrt_tls_session_allow_ed25519(void* handle, int allow) { XL6_TlsSession* s = (XL6_TlsSession*)handle; if ( s != 0 ) { xrtNetTlsSessionSetAllowTLS12Ed25519(s->value, allow != 0); } }\n\n", out);
    xl6OutputPuts("void* xl6_xrt_tls_resume_wrap(void* handle) { return handle; }\nlong long xl6_xrt_tls_resume_destroy(void* handle) { xrtNetTlsResumeDestroy((xtlsresume*)handle); return 0; }\nvoid* xl6_xrt_tls_resume_native(void* handle) { return handle; }\n\n", out);
}
